function gen(w,h,text,bg,fg){
  w=Math.max(1,Math.floor(w||300)); h=Math.max(1,Math.floor(h||150));
  text=text||(w+'×'+h); bg=bg||'#cccccc'; fg=fg||'#333333';
  var fsz=Math.max(10,Math.min(w,h)/6|0);
  var svg='<svg xmlns="http://www.w3.org/2000/svg" width="'+w+'" height="'+h+'" viewBox="0 0 '+w+' '+h+'">'
    +'<rect width="100%" height="100%" fill="'+bg+'"/>'
    +'<text x="50%" y="50%" fill="'+fg+'" font-family="sans-serif" font-size="'+fsz+'" text-anchor="middle" dominant-baseline="central">'+text+'</text>'
    +'</svg>';
  return svg;
}
var EXPORTS={gen:gen};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SvgPlaceholderForgePure = EXPORTS; }
